INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('thai-hu-kiem-ton', 'Thái Hư Kiếm Tôn', 'Thiên địa đại biến, linh khí khôi phục. Tô Nguyệt mang theo ký ức mơ hồ về một kiếp trước bước vào con đường tu luyện, đối đầu với các tông môn lớn và những bí mật bị chôn vùi từ thời thượng cổ.', 'demo/covers/thai-hu-kiem-ton.svg', 'NOVEL', 'ONGOING', 'PUBLISHED', NULL, @u_author1, 13, 6798, 6, 13, 5, 5, NOW(6) - INTERVAL 135360 MINUTE, NOW(6) - INTERVAL 3566 MINUTE, NOW(6) - INTERVAL 138240 MINUTE);
