INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('tieng-go-cuoi-hanh-lang', 'Tiếng Gõ Cuối Hành Lang', 'Tô Nguyệt thuê được căn phòng giá rẻ bất ngờ ở một khu tập thể cũ. Đêm nào cũng có tiếng gõ cửa đúng ba giờ sáng, và những người hàng xóm dường như đều đang che giấu một bí mật rùng rợn.', 'demo/covers/tieng-go-cuoi-hanh-lang.svg', 'NOVEL', 'ONGOING', 'PUBLISHED', NULL, @u_author1, 15, 2460, 1, 9, 2, 5, NOW(6) - INTERVAL 99360 MINUTE, NOW(6) - INTERVAL 1616 MINUTE, NOW(6) - INTERVAL 102240 MINUTE);
