INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('tinh-ha-dao-quan', 'Tinh Hà Đạo Quân', 'Khương Nhiên vốn chỉ là đệ tử ngoại môn có linh căn tầm thường, bị cả tông môn xem nhẹ. Một lần rơi xuống vực sâu, cậu nhặt được mảnh ngọc cổ chứa truyền thừa của một vị tiên nhân đã ngã xuống. Từ đó con đường tu tiên mở ra: luyện khí, trúc cơ, độ kiếp, từng bước leo lên đỉnh cao của giới tu chân.', 'demo/covers/tinh-ha-dao-quan.svg', 'NOVEL', 'COMPLETED', 'PUBLISHED', NULL, @u_author2, 25, 14927, 5, 18, 5, 3, NOW(6) - INTERVAL 46080 MINUTE, NOW(6) - INTERVAL 25920 MINUTE, NOW(6) - INTERVAL 48960 MINUTE);
