INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('tho-san-so-mot', 'Thợ Săn Số Một', 'Cổng hầm ngục xuất hiện khắp thế giới. Trần Vũ, thợ săn hạng thấp nhất, nhận được hệ thống cho phép thăng cấp không giới hạn sau một lần suýt chết.', 'demo/covers/tho-san-so-mot.svg', 'NOVEL', 'COMPLETED', 'PUBLISHED', NULL, @u_author2, 28, 4287, 4, 7, 2, 6, NOW(6) - INTERVAL 159840 MINUTE, NOW(6) - INTERVAL 23040 MINUTE, NOW(6) - INTERVAL 162720 MINUTE);
