INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('nang-cuoi-thang-tu', 'Nắng Cuối Tháng Tư', 'Chuyện tình nhẹ nhàng giữa Trần Vũ, cô biên tập viên trẻ vừa chuyển về thành phố, và người hàng xóm ít nói ở căn hộ đối diện. Hai con người từng tổn thương học cách tin tưởng và yêu thương thêm một lần nữa.', 'demo/covers/nang-cuoi-thang-tu.svg', 'NOVEL', 'ONGOING', 'PUBLISHED', NULL, @u_author1, 21, 1407, 1, 0, 0, 6, NOW(6) - INTERVAL 100800 MINUTE, NOW(6) - INTERVAL 2714 MINUTE, NOW(6) - INTERVAL 103680 MINUTE);
