INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('bong-nguoi-cuoi-hanh-lang', 'Bóng Người Cuối Hành Lang', 'Khương Nhiên thuê được căn phòng giá rẻ bất ngờ ở một khu tập thể cũ. Đêm nào cũng có tiếng gõ cửa đúng ba giờ sáng, và những người hàng xóm dường như đều đang che giấu một bí mật rùng rợn.', 'demo/covers/bong-nguoi-cuoi-hanh-lang.svg', 'NOVEL', 'ONGOING', 'PUBLISHED', NULL, @u_author3, 22, 811, 0, 0, 0, 0, NOW(6) - INTERVAL 44640 MINUTE, NOW(6) - INTERVAL 203 MINUTE, NOW(6) - INTERVAL 47520 MINUTE);
