INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('ho-so-khong-loi-giai', 'Hồ Sơ Không Lời Giải', 'Thám tử tư Khương Nhiên nhận một vụ tìm người tưởng chừng đơn giản, rồi phát hiện nó dính tới chuỗi án mạng chưa có lời giải suốt mười năm. Mỗi chương là một manh mối, mỗi manh mối lật ngược suy luận trước đó.', 'demo/covers/ho-so-khong-loi-giai.svg', 'NOVEL', 'COMPLETED', 'PUBLISHED', NULL, @u_author1, 29, 6079, 4, 8, 2, 7, NOW(6) - INTERVAL 40320 MINUTE, NOW(6) - INTERVAL 31680 MINUTE, NOW(6) - INTERVAL 43200 MINUTE);
