INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('tin-hieu-tu-sao-hoa', 'Tín Hiệu Từ Sao Hỏa', 'Năm 2147, một tín hiệu lạ từ rìa hệ Mặt Trời làm tê liệt toàn bộ mạng lưới vệ tinh. Kỹ sư Tô Nguyệt cùng phi hành đoàn của trạm không gian cuối cùng phải tìm ra nguồn phát trước khi quá muộn.', 'demo/covers/tin-hieu-tu-sao-hoa.svg', 'COMIC', 'ONGOING', 'PUBLISHED', NULL, @u_author3, 12, 566, 0, 5, 1, 0, NOW(6) - INTERVAL 47520 MINUTE, NOW(6) - INTERVAL 3214 MINUTE, NOW(6) - INTERVAL 50400 MINUTE);
