INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('cu-sut-tuoi-17', 'Cú Sút Tuổi 17', 'Đội bóng trường huyện chưa từng thắng nổi một trận ở giải tỉnh. Lâm Phong, cậu học sinh mới chuyển về với đôi chân trái kỳ lạ, cùng đồng đội viết nên một mùa hè không thể quên.', 'demo/covers/cu-sut-tuoi-17.svg', 'COMIC', 'ONGOING', 'PUBLISHED', NULL, @u_author1, 8, 697, 2, 4, 1, 0, NOW(6) - INTERVAL 141120 MINUTE, NOW(6) - INTERVAL 2694 MINUTE, NOW(6) - INTERVAL 144000 MINUTE);
