INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('bep-lua-nha-ba', 'Bếp Lửa Nhà Bà', 'Hạ Linh nghỉ việc ở thành phố, về quê tiếp quản quán ăn nhỏ của bà. Mỗi chương là một món ăn và câu chuyện của người khách ghé quán. Truyện chữa lành, nhẹ nhàng, đọc xong thấy đói bụng.', 'demo/covers/bep-lua-nha-ba.svg', 'COMIC', 'PAUSED', 'PUBLISHED', NULL, @u_author2, 12, 2893, 1, 4, 1, 4, NOW(6) - INTERVAL 92160 MINUTE, NOW(6) - INTERVAL 21600 MINUTE, NOW(6) - INTERVAL 95040 MINUTE);
