INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('cuu-thien-dan-de', 'Cửu Thiên Đan Đế', 'Thiên địa đại biến, linh khí khôi phục. Diệp An mang theo ký ức mơ hồ về một kiếp trước bước vào con đường tu luyện, đối đầu với các tông môn lớn và những bí mật bị chôn vùi từ thời thượng cổ.', 'demo/covers/cuu-thien-dan-de.svg', 'NOVEL', 'ONGOING', 'PUBLISHED', NULL, @u_author1, 18, 3008, 4, 3, 1, 2, NOW(6) - INTERVAL 74880 MINUTE, NOW(6) - INTERVAL 4987 MINUTE, NOW(6) - INTERVAL 77760 MINUTE);
