INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('ky-uc-mua-hoa-sua', 'Ký Ức Mùa Hoa Sữa', 'Chuyện tình nhẹ nhàng giữa Trần Vũ, cô biên tập viên trẻ vừa chuyển về thành phố, và người hàng xóm ít nói ở căn hộ đối diện. Hai con người từng tổn thương học cách tin tưởng và yêu thương thêm một lần nữa.', 'demo/covers/ky-uc-mua-hoa-sua.svg', 'COMIC', 'ONGOING', 'PUBLISHED', NULL, @u_author2, 15, 1273, 1, 0, 0, 3, NOW(6) - INTERVAL 56160 MINUTE, NOW(6) - INTERVAL 1605 MINUTE, NOW(6) - INTERVAL 59040 MINUTE);
