INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('than-y-pha-thien', 'Thần Y Phá Thiên', 'Nữ bác sĩ quân y Trần Vũ xuyên không về thời cổ đại, trở thành đích nữ bị ghẻ lạnh của phủ tướng quân. Với y thuật và bản lĩnh của mình, nàng từng bước thay đổi số phận.', 'demo/covers/than-y-pha-thien.svg', 'NOVEL', 'PAUSED', 'PUBLISHED', NULL, @u_author3, 28, 5808, 3, 24, 7, 2, NOW(6) - INTERVAL 126720 MINUTE, NOW(6) - INTERVAL 21600 MINUTE, NOW(6) - INTERVAL 129600 MINUTE);
