INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('manh-vuon-cuoi-ngo', 'Mảnh Vườn Cuối Ngõ', 'Lâm Phong nghỉ việc ở thành phố, về quê tiếp quản quán ăn nhỏ của bà. Mỗi chương là một món ăn và câu chuyện của người khách ghé quán. Truyện chữa lành, nhẹ nhàng, đọc xong thấy đói bụng.', 'demo/covers/manh-vuon-cuoi-ngo.svg', 'NOVEL', 'ONGOING', 'PUBLISHED', NULL, @u_author3, 14, 4813, 4, 0, 0, 6, NOW(6) - INTERVAL 70560 MINUTE, NOW(6) - INTERVAL 2895 MINUTE, NOW(6) - INTERVAL 73440 MINUTE);
