INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('nguoi-choi-toi-thuong', 'Người Chơi Tối Thượng', 'Tỉnh dậy trong một thế giới vận hành theo luật trò chơi, Bạch Dương chỉ có một kỹ năng bị coi là vô dụng. Nhưng hệ thống của cậu có một dòng mô tả ẩn mà không người chơi nào khác nhìn thấy.', 'demo/covers/nguoi-choi-toi-thuong.svg', 'NOVEL', 'COMPLETED', 'PUBLISHED', NULL, @u_author1, 20, 15270, 7, 21, 6, 3, NOW(6) - INTERVAL 110880 MINUTE, NOW(6) - INTERVAL 31680 MINUTE, NOW(6) - INTERVAL 113760 MINUTE);
