INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('thanh-van-kiem-ton', 'Thanh Vân Kiếm Tôn', 'Tô Nguyệt vốn chỉ là đệ tử ngoại môn có linh căn tầm thường, bị cả tông môn xem nhẹ. Một lần rơi xuống vực sâu, cậu nhặt được mảnh ngọc cổ chứa truyền thừa của một vị tiên nhân đã ngã xuống. Từ đó con đường tu tiên mở ra: luyện khí, trúc cơ, độ kiếp, từng bước leo lên đỉnh cao của giới tu chân.', 'demo/covers/thanh-van-kiem-ton.svg', 'COMIC', 'ONGOING', 'PUBLISHED', NULL, @u_author3, 8, 2872, 4, 7, 2, 2, NOW(6) - INTERVAL 37440 MINUTE, NOW(6) - INTERVAL 4701 MINUTE, NOW(6) - INTERVAL 40320 MINUTE);
