INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('tin-hieu-tro-tan', 'Tín Hiệu Tro Tàn', 'Năm 2147, một tín hiệu lạ từ rìa hệ Mặt Trời làm tê liệt toàn bộ mạng lưới vệ tinh. Kỹ sư Tô Nguyệt cùng phi hành đoàn của trạm không gian cuối cùng phải tìm ra nguồn phát trước khi quá muộn.', 'demo/covers/tin-hieu-tro-tan.svg', 'NOVEL', 'COMPLETED', 'PUBLISHED', NULL, @u_author3, 22, 7520, 2, 19, 5, 9, NOW(6) - INTERVAL 73440 MINUTE, NOW(6) - INTERVAL 28800 MINUTE, NOW(6) - INTERVAL 76320 MINUTE);
