INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('manh-vuon-ven-doi', 'Mảnh Vườn Ven Đồi', 'Một mảnh vườn bỏ hoang, một căn bếp củi và Tô Nguyệt bắt đầu lại từ con số không: trồng rau, nuôi gà, mở tiệm bánh đầu tiên của làng.', 'demo/covers/manh-vuon-ven-doi.svg', 'NOVEL', 'COMPLETED', 'PUBLISHED', NULL, @u_author2, 19, 8401, 4, 11, 3, 5, NOW(6) - INTERVAL 37440 MINUTE, NOW(6) - INTERVAL 15840 MINUTE, NOW(6) - INTERVAL 40320 MINUTE);
