INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('tho-san-ham-nguc', 'Thợ Săn Hầm Ngục', 'Tỉnh dậy trong một thế giới vận hành theo luật trò chơi, Trần Vũ chỉ có một kỹ năng bị coi là vô dụng. Nhưng hệ thống của cậu có một dòng mô tả ẩn mà không người chơi nào khác nhìn thấy.', 'demo/covers/tho-san-ham-nguc.svg', 'NOVEL', 'ONGOING', 'HIDDEN', 'Nội dung chương 3 sao chép từ tác phẩm khác. Vui lòng chỉnh sửa rồi liên hệ quản trị viên.', @u_author3, 26, 5016, 0, 0, 0, 0, NOW(6) - INTERVAL 38880 MINUTE, NOW(6) - INTERVAL 927 MINUTE, NOW(6) - INTERVAL 41760 MINUTE);
INSERT INTO story_genre (story_id, genre_id) SELECT @s59, id FROM genre WHERE slug IN ('hanh-dong', 'game', 'he-thong');
