INSERT INTO story (slug, title, description, cover_path, type, status, visibility, hidden_reason, author_id, chapter_count, view_count, follow_count, rating_sum, rating_count, comment_count, published_at, last_chapter_at, created_at) VALUES ('cau-lac-bo-sieu-quay', 'Câu Lạc Bộ Siêu Quậy', 'Lâm Phong chuyển trường giữa học kỳ và bị xếp ngồi cạnh lớp trưởng khó tính nhất khối. Một năm học ồn ào và đáng nhớ bắt đầu từ đó.', 'demo/covers/cau-lac-bo-sieu-quay.svg', 'COMIC', 'ONGOING', 'DRAFT', NULL, @u_author3, 13, 816, 0, 0, 0, 0, NULL, NOW(6) - INTERVAL 5321 MINUTE, NOW(6) - INTERVAL 123840 MINUTE);
